  /// Banned user's {\@link economic_political_board_administrator_roles.id}.
  user_id String @db.Uuid

  /// Administrator's {\@link economic_political_board_administrator_roles.id}
  /// who issued this ban.
  banned_by_admin_id String @db.Uuid

  /// The reason for the ban. Must be specific and documented.
  reason String

  /// Timestamp when the ban was issued.
  created_at DateTime @db.Timestamptz

