  typia.assert(retrievedSection);
  TestValidator.equals(
    "section name unchanged after failed update",
    retrievedSection.name,
    originalName,
  );
  TestValidator.equals(
    "section description unchanged after failed update",
    retrievedSection.description,
    originalDescription,
  );
}

