@Controller("/economicPoliticalBoard/auth/member")
export class EconomicpoliticalboardAuthMemberController {
  /**
   * Register a new member account for the Economic Political Board discussion platform.
   *
   * This operation creates a new user account with email and password authentication, along with an associated profile containing displayName and bio. The registration process validates the email format and ensures it is unique in the economic_political_board_users table before creating the account. The password is securely hashed using a strong algorithm (bcrypt or Argon2) and stored as passwordHash in the database.
   *
   * Upon successful registration, a new Profile record is automatically created with the displayName and bio provided during registration. The profile is linked to the user via the userId foreign key relationship. Both the User and Profile records are created within a single database transaction to maintain referential integrity.
   *
   * After account creation, the system generates JWT tokens (access token and refresh token) for authentication. The access token contains the user ID, email, displayName, and member role claims. The refresh token is stored server-side for token renewal. Both tokens are included in the IAuthorized response.
   *
   * The registration endpoint rejects requests with 400 Bad Request if the email is already registered, the password does not meet minimum length requirements, or the displayName/bio have invalid formats. New users are created with isBanned=false, allowing immediate access to member features.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Registration data including email, password, displayName, and optional bio
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Create a new user account and profile by: 1) Validating email format and uniqueness against economic_political_board_users table, 2) Hashing password using bcrypt or Argon2 before storing as passwordHash, 3) Creating user record with email and passwordHash, 4) Automatically creating associated profile record with displayName from registration data, 5) Checking isBanned flag on creation (should be false for new users), 6) Returning JWT tokens (accessToken, refreshToken) and IAuthorized response with user ID, email, displayName. Reject with 400 if email already exists or validation fails. Reject with 403 if registration endpoint is disabled.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEconomicPoliticalBoardMember.IJoin,
  ): Promise<IEconomicPoliticalBoardMember.IAuthorized> {
    try {
      return await postEconomicPoliticalBoardAuthMemberJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticate a registered member using email and password credentials.
   *
   * This operation validates user credentials against the economic_political_board_users table to authenticate the member. The process involves querying the user record by email, hashing the provided password with the same algorithm used during registration (bcrypt or Argon2), and performing a constant-time comparison with the stored passwordHash to prevent timing attacks.
   *
   * Before issuing tokens, the system checks the isBanned flag on the user record. If the user has been banned (isBanned=true), the operation rejects authentication with a 401 Unauthorized response and includes the banReason from the banReason field. The banAt timestamp indicates when the ban was issued. Banned users cannot authenticate regardless of credential validity.
   *
   * Upon successful credential validation, the system generates a new JWT access token containing the user ID, email, displayName, and member role in the claims payload. A new refresh token is also generated and stored server-side for token renewal operations. Both tokens are included in the IAuthorized response body.
   *
   * The endpoint implements rate limiting to prevent brute-force attacks. After a configurable number of failed attempts, further requests are temporarily throttled. Failed authentication attempts do not reveal whether the email exists or the password was incorrect, maintaining user privacy and security.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Login credentials including email and password
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Authenticate member by validating credentials: 1) Query economic_political_board_users by email, 2) Hash provided password and compare with stored passwordHash using constant-time comparison, 3) Check isBanned flag and banReason/banAt if banned, 4) Reject with 401 if password invalid or user is banned, 5) Create new JWT access token with user ID, email, displayName, member role, 6) Generate new refresh token and store in server-side token store, 7) Return IAuthorized response with both tokens. Handle rate limiting per security policy.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEconomicPoliticalBoardMember.ILogin,
  ): Promise<IEconomicPoliticalBoardMember.IAuthorized> {
    try {
      return await postEconomicPoliticalBoardAuthMemberLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Renew the JWT access token using a valid refresh token.
   *
   * This operation allows members to obtain a new access token without re-authenticating with credentials. The refresh token is a long-lived token issued during registration or login that can be exchanged for a new access token. This mechanism maintains seamless authentication while minimizing credential exposure.
   *
   * The operation validates the refresh token by checking its signature, expiration time, and existence in the server-side token store. If the token is valid and not expired, a new access token is generated with the same user claims (user ID, email, displayName, member role). The old refresh token is revoked and replaced with a new refresh token, implementing token rotation for enhanced security.
   *
   * Token rotation prevents refresh token replay attacks by ensuring each refresh token can only be used once. The new refresh token is returned in the IAuthorized response alongside the new access token. Members should store the new refresh token and discard the old one.
   *
   * The operation rejects requests with 401 Unauthorized if the refresh token has expired, the signature is invalid, the token has been revoked, or the token does not exist in the server-side store. Expired or invalid tokens require re-authentication via the login endpoint.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token for token renewal
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Renew JWT access token using refresh token: 1) Extract refresh token from request body, 2) Validate token signature and expiration against server-side token store, 3) If valid, generate new access token with same claims, 4) Generate new refresh token and rotate old one, 5) Return IAuthorized response with new tokens. Reject with 401 if refresh token expired, invalid, or revoked.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEconomicPoliticalBoardMember.IRefresh,
  ): Promise<IEconomicPoliticalBoardMember.IAuthorized> {
    try {
      return await postEconomicPoliticalBoardAuthMemberRefresh({
        body,
